#include "kernel.h"
#include <hls_math.h>

// ---------------------------------------------------------------------------
// Helper: complex multiply
// ---------------------------------------------------------------------------
static complex_t cmul(complex_t a, complex_t b) {
#pragma HLS INLINE
    complex_t r;
    r.re = a.re * b.re - a.im * b.im;
    r.im = a.re * b.im + a.im * b.re;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: complex add
// ---------------------------------------------------------------------------
static complex_t cadd(complex_t a, complex_t b) {
#pragma HLS INLINE
    complex_t r;
    r.re = a.re + b.re;
    r.im = a.im + b.im;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: complex conjugate
// ---------------------------------------------------------------------------
static complex_t cconj(complex_t a) {
#pragma HLS INLINE
    complex_t r;
    r.re =  a.re;
    r.im = -a.im;
    return r;
}

// ---------------------------------------------------------------------------
// Helper: |z|  (magnitude)
// ---------------------------------------------------------------------------
static fixed_t cabs(complex_t a) {
#pragma HLS INLINE
    float re_f = (float)a.re;
    float im_f = (float)a.im;
    return (fixed_t)hls::sqrt(re_f * re_f + im_f * im_f);
}

// ---------------------------------------------------------------------------
// Helper: angle of complex number  (atan2(im, re))
// ---------------------------------------------------------------------------
static fixed_t cangle(complex_t a) {
#pragma HLS INLINE
    float re_f = (float)a.re;
    float im_f = (float)a.im;
    return (fixed_t)hls::atan2(im_f, re_f);
}

// ---------------------------------------------------------------------------
// kernel_top
// ---------------------------------------------------------------------------
void kernel_top(
    complex_t A_in[N][N],
    int       max_iter,
    int      *out_iters,
    complex_t eigenvalues[N],
    complex_t eigenvectors[N][N]
)
{
#pragma HLS INTERFACE ap_none port=A_in
#pragma HLS INTERFACE ap_none port=max_iter
#pragma HLS INTERFACE ap_none port=out_iters
#pragma HLS INTERFACE ap_none port=eigenvalues
#pragma HLS INTERFACE ap_none port=eigenvectors
#pragma HLS INTERFACE ap_ctrl_hs port=return

    // Local working copy of A
    complex_t A[N][N];
    INIT_A_OUTER: for (int i = 0; i < N; i++) {
        INIT_A_INNER: for (int j = 0; j < N; j++) {
            A[i][j] = A_in[i][j];
        }
    }

    // V = identity (complex)
    complex_t V[N][N];
    INIT_V_OUTER: for (int i = 0; i < N; i++) {
        INIT_V_INNER: for (int j = 0; j < N; j++) {
            V[i][j].re = (i == j) ? (fixed_t)1 : (fixed_t)0;
            V[i][j].im = (fixed_t)0;
        }
    }

    int final_iter = 0;

    JACOBI_OUTER: for (int z = 0; z < 2000; z++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=2000

        if (z >= max_iter) {
            final_iter = z;
            break;
        }

        // Find pivot (p, q) with largest |A[i][j]|, i < j
        fixed_t off_diag_max = (fixed_t)0;
        int p = 0, q = 1;

        PIVOT_I: for (int i = 0; i < N; i++) {
            PIVOT_J: for (int j = i + 1; j < N; j++) {
                fixed_t mag = cabs(A[i][j]);
                if (mag > off_diag_max) {
                    off_diag_max = mag;
                    p = i;
                    q = j;
                }
            }
        }

        // Convergence check: 1e-8 in fixed-point
        if (off_diag_max < (fixed_t)1e-8) {
            final_iter = z;
            break;
        }

        final_iter = z;

        // Compute rotation parameters
        complex_t a_pq  = A[p][q];
        fixed_t   a_pp  = A[p][p].re;   // diagonal is real for Hermitian
        fixed_t   a_qq  = A[q][q].re;

        fixed_t mag_pq = cabs(a_pq);
        fixed_t denom  = a_pp - a_qq;

        float theta_f;
        {
            float num_f = 2.0f * (float)mag_pq;
            float den_f = (float)denom;
            theta_f = 0.5f * hls::atan2(num_f, den_f);   // atan(x) = atan2(x,1), but use atan2 for safety
        }
        fixed_t theta = (fixed_t)theta_f;

        fixed_t phi = -cangle(a_pq);

        fixed_t cos_theta = (fixed_t)hls::cos((float)theta);
        fixed_t sin_theta = (fixed_t)hls::sin((float)theta);

        // exp(-i*phi) = cos(phi) - i*sin(phi)
        // exp(+i*phi) = cos(phi) + i*sin(phi)
        float phi_f   = (float)phi;
        fixed_t cos_phi = (fixed_t)hls::cos(phi_f);
        fixed_t sin_phi = (fixed_t)hls::sin(phi_f);   // phi already negated above

        complex_t exp_neg_phi;  // exp(-i*phi) but phi = -angle(a_pq), so exp(-i*phi)=exp(i*angle(a_pq))
        exp_neg_phi.re = cos_phi;
        exp_neg_phi.im = -sin_phi;   // e^{i*phi} = cos(phi)+i*sin(phi), phi here is -angle

        complex_t exp_pos_phi;
        exp_pos_phi.re = cos_phi;
        exp_pos_phi.im = sin_phi;

        // U matrix (only non-trivial entries; rest is identity-like)
        // U[p][p] =  cos(theta)
        // U[p][q] =  sin(theta)*exp(-i*phi)
        // U[q][p] =  sin(theta)*exp(+i*phi)
        // U[q][q] = -cos(theta)

        complex_t U_pp; U_pp.re =  cos_theta; U_pp.im = (fixed_t)0;
        complex_t U_qq; U_qq.re = -cos_theta; U_qq.im = (fixed_t)0;

        complex_t U_pq;
        U_pq.re = sin_theta * exp_neg_phi.re;
        U_pq.im = sin_theta * exp_neg_phi.im;

        complex_t U_qp;
        U_qp.re = sin_theta * exp_pos_phi.re;
        U_qp.im = sin_theta * exp_pos_phi.im;

        // ---------------------------------------------------------------------------
        // A <- U^H * A * U
        // We do this in two steps: first B = U^H * A, then A = B * U
        // Only rows/columns p and q change.
        // ---------------------------------------------------------------------------

        // Step 1: B = U^H * A  (acts on rows p and q)
        complex_t B[N][N];

        // Copy all rows first
        COPY_B_I: for (int i = 0; i < N; i++) {
            COPY_B_J: for (int j = 0; j < N; j++) {
                B[i][j] = A[i][j];
            }
        }

        // Row p and row q of B  (U^H row mixing: conj of U columns)
        // U^H[p, :] = conj(U[:, p]) = {U_pp*, U_qp*}  (only at positions p and q)
        // U^H[q, :] = conj(U[:, q]) = {U_pq*, U_qq*}
        UPDATE_B_J: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            complex_t Apj = A[p][j];
            complex_t Aqj = A[q][j];

            // B[p][j] = conj(U_pp)*A[p][j] + conj(U_qp)*A[q][j]
            complex_t cU_pp = cconj(U_pp);
            complex_t cU_qp = cconj(U_qp);
            B[p][j] = cadd(cmul(cU_pp, Apj), cmul(cU_qp, Aqj));

            // B[q][j] = conj(U_pq)*A[p][j] + conj(U_qq)*A[q][j]
            complex_t cU_pq = cconj(U_pq);
            complex_t cU_qq = cconj(U_qq);
            B[q][j] = cadd(cmul(cU_pq, Apj), cmul(cU_qq, Aqj));
        }

        // Step 2: A = B * U  (acts on cols p and q)
        // Copy B into A first
        COPY_A2_I: for (int i = 0; i < N; i++) {
            COPY_A2_J: for (int j = 0; j < N; j++) {
                A[i][j] = B[i][j];
            }
        }

        UPDATE_A_I: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            complex_t Bip = B[i][p];
            complex_t Biq = B[i][q];

            // A[i][p] = B[i][p]*U_pp + B[i][q]*U_qp
            A[i][p] = cadd(cmul(Bip, U_pp), cmul(Biq, U_qp));

            // A[i][q] = B[i][p]*U_pq + B[i][q]*U_qq
            A[i][q] = cadd(cmul(Bip, U_pq), cmul(Biq, U_qq));
        }

        // Force off-diagonal pivot entries to zero
        A[p][q].re = (fixed_t)0; A[p][q].im = (fixed_t)0;
        A[q][p].re = (fixed_t)0; A[q][p].im = (fixed_t)0;

        // ---------------------------------------------------------------------------
        // V = V * U   (only cols p and q change)
        // ---------------------------------------------------------------------------
        UPDATE_V_I: for (int i = 0; i < N; i++) {
#pragma HLS PIPELINE II=1
            complex_t Vip = V[i][p];
            complex_t Viq = V[i][q];

            V[i][p] = cadd(cmul(Vip, U_pp), cmul(Viq, U_qp));
            V[i][q] = cadd(cmul(Vip, U_pq), cmul(Viq, U_qq));
        }

    } // end JACOBI_OUTER

    // Write outputs
    *out_iters = final_iter;

    DIAG_OUT: for (int i = 0; i < N; i++) {
        eigenvalues[i] = A[i][i];
    }

    EIG_V_I: for (int i = 0; i < N; i++) {
        EIG_V_J: for (int j = 0; j < N; j++) {
            eigenvectors[i][j] = V[i][j];
        }
    }
}
