#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <cmath>
#include "kernel.h"

// ---------------------------------------------------------------------------
// Paths
// ---------------------------------------------------------------------------
static const char *IO_DIR  = "/home/mbenton/verilog_rapid_prototyping/conversion_010/eig_10_io/";
static const char *SIM_DIR = "/home/mbenton/verilog_rapid_prototyping/conversion_010/build/sim/";

// ---------------------------------------------------------------------------
// Helper: open a file, abort on failure
// ---------------------------------------------------------------------------
static FILE *xfopen(const char *path, const char *mode) {
    FILE *f = fopen(path, mode);
    if (!f) {
        fprintf(stderr, "ERROR: cannot open '%s'\n", path);
        exit(1);
    }
    return f;
}

// ---------------------------------------------------------------------------
// main
// ---------------------------------------------------------------------------
int main(void) {

    // -----------------------------------------------------------------------
    // Read in_A.txt  – call index 0
    // Format: each line = "real imag"   (row-major, 10*10 = 100 elements)
    // We skip to line 0 (first call).
    // -----------------------------------------------------------------------
    char path[512];

    complex_t A_in[N][N];
    {
        snprintf(path, sizeof(path), "%sin_A.txt", IO_DIR);
        FILE *f = xfopen(path, "r");
        // call 0 → elements 0..99
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re, im;
                if (fscanf(f, "%lf %lf", &re, &im) != 2) {
                    fprintf(stderr, "ERROR: unexpected EOF in in_A.txt at [%d][%d]\n", i, j);
                    fclose(f);
                    exit(1);
                }
                A_in[i][j].re = (fixed_t)re;
                A_in[i][j].im = (fixed_t)im;
            }
        }
        fclose(f);
    }

    // -----------------------------------------------------------------------
    // Read in_max_iter.txt – call index 0  (scalar, no imaginary part)
    // -----------------------------------------------------------------------
    int max_iter_val = 2000;
    {
        snprintf(path, sizeof(path), "%sin_max_iter.txt", IO_DIR);
        FILE *f = xfopen(path, "r");
        long long v;
        if (fscanf(f, "%lld", &v) != 1) {
            fprintf(stderr, "ERROR: unexpected EOF in in_max_iter.txt\n");
            fclose(f);
            exit(1);
        }
        max_iter_val = (int)v;
        fclose(f);
    }

    // -----------------------------------------------------------------------
    // Call kernel_top
    // -----------------------------------------------------------------------
    int       out_iters = 0;
    complex_t eigenvalues[N];
    complex_t eigenvectors[N][N];

    kernel_top(A_in, max_iter_val, &out_iters, eigenvalues, eigenvectors);

    // -----------------------------------------------------------------------
    // Write out_0.txt  (scalar int64)
    // -----------------------------------------------------------------------
    {
        snprintf(path, sizeof(path), "%sout_0.txt", SIM_DIR);
        FILE *f = xfopen(path, "w");
        fprintf(f, "%d\n", out_iters);
        fclose(f);
    }

    // -----------------------------------------------------------------------
    // Write out_1.txt  (complex, shape [10])
    // -----------------------------------------------------------------------
    {
        snprintf(path, sizeof(path), "%sout_1.txt", SIM_DIR);
        FILE *f = xfopen(path, "w");
        for (int i = 0; i < N; i++) {
            fprintf(f, "%.17g %.17g\n",
                    (double)eigenvalues[i].re,
                    (double)eigenvalues[i].im);
        }
        fclose(f);
    }

    // -----------------------------------------------------------------------
    // Write out_2.txt  (complex, shape [10][10], row-major)
    // -----------------------------------------------------------------------
    {
        snprintf(path, sizeof(path), "%sout_2.txt", SIM_DIR);
        FILE *f = xfopen(path, "w");
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                fprintf(f, "%.17g %.17g\n",
                        (double)eigenvectors[i][j].re,
                        (double)eigenvectors[i][j].im);
            }
        }
        fclose(f);
    }

    printf("Simulation complete.\n");
    printf("  out_iters     = %d\n", out_iters);
    printf("  Results written to: %s\n", SIM_DIR);
    return 0;
}
